actions.script:
ec.message.pushErrors()
let found = null
try {
    found = ec.service.sync().name('mantle.humanres.RecruitingServices.get#OfferLetter')
        .parameters({employmentOfferId: employmentOfferId || ''}).requireNewTransaction(true).call() || null
    if (ec.message.hasError()) found = null
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
const enc = text => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const L = text => enc(ec.l10n.localize(text))
printHtml = !found ? '<p>' + L('This offer is not available') + '</p>'
    : found.issued ? '<p>' + L('This offer is issued: open its letter as it was stored, from the offer') + '</p>'
    : found.letterHtml
printUrl = '/apps/People/Staffing/OfferLetter?renderMode=html-print&employmentOfferId=' + encodeURIComponent(employmentOfferId || '')
